// Directory domain synchronization statistics
type DirectoryDomainSyncStats struct {
	// All the historical delta sync are counted in calculating the average delta sync time in milliseconds. format: int64
	AvgDeltaSyncTime *int64
	// All the historical full sync are counted in calculating the average full sync time in milliseconds. format: int64
	AvgFullSyncTime *int64
	// Possible values are:
	//
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_CURRENT_STATE_IDLE
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_CURRENT_STATE_FULL_SYNC
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_CURRENT_STATE_DELTA_SYNC
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_CURRENT_STATE_SELECTIVE_FULL_SYNC
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_CURRENT_STATE_SELECTIVE_DELTA_SYNC
	//
	//  Current running state of the directory domain in synchronization life cycle. It could be one of the following five states. SELECTIVE_FULL_SYNC and SELECTIVE_DELTA_SYNC are sync states for selective sync.
	CurrentState *string
	// Since what time the current state has begun. The time is expressed in millisecond epoch time. format: int64
	CurrentStateBeginTime *int64
	// number of successful historical delta sync initiated either by system or by API request. format: int64
	NumDeltaSync *int64
	// number of successful historical full sync initiated either by system or by API request. format: int64
	NumFullSync *int64
	// Directory domain previous sync ending time expressed in millisecond epoch time. format: int64
	PrevSyncEndTime *int64
	// Directory domain previous sync status error if last status was failure.
	PrevSyncError *string
	// Possible values are:
	//
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_STATUS_SUCCESS
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_STATUS_FAILURE
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_STATUS_UNKNOWN
	//
	//  Directory domain previous sync status. It could be one of the following two states.
	PrevSyncStatus *string
	// Possible values are:
	//
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_TYPE_IDLE
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_TYPE_FULL_SYNC
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_TYPE_DELTA_SYNC
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_TYPE_SELECTIVE_FULL_SYNC
	// * DirectoryDomainSyncStats#DirectoryDomainSyncStats_PREV_SYNC_TYPE_SELECTIVE_DELTA_SYNC
	//
	//  Directory domain previous sync type. It could be one of the following five states. Right after the directory domain is configured, this field is set to IDLE.
	PrevSyncType *string
}

const DirectoryDomainSyncStats_CURRENT_STATE_IDLE = "IDLE"
const DirectoryDomainSyncStats_CURRENT_STATE_FULL_SYNC = "FULL_SYNC"
const DirectoryDomainSyncStats_CURRENT_STATE_DELTA_SYNC = "DELTA_SYNC"
const DirectoryDomainSyncStats_CURRENT_STATE_SELECTIVE_FULL_SYNC = "SELECTIVE_FULL_SYNC"
const DirectoryDomainSyncStats_CURRENT_STATE_SELECTIVE_DELTA_SYNC = "SELECTIVE_DELTA_SYNC"
const DirectoryDomainSyncStats_PREV_SYNC_STATUS_SUCCESS = "SUCCESS"
const DirectoryDomainSyncStats_PREV_SYNC_STATUS_FAILURE = "FAILURE"
const DirectoryDomainSyncStats_PREV_SYNC_STATUS_UNKNOWN = "UNKNOWN"
const DirectoryDomainSyncStats_PREV_SYNC_TYPE_IDLE = "IDLE"
const DirectoryDomainSyncStats_PREV_SYNC_TYPE_FULL_SYNC = "FULL_SYNC"
const DirectoryDomainSyncStats_PREV_SYNC_TYPE_DELTA_SYNC = "DELTA_SYNC"
const DirectoryDomainSyncStats_PREV_SYNC_TYPE_SELECTIVE_FULL_SYNC = "SELECTIVE_FULL_SYNC"
