const TransportNodeCollectionState_STATE_FAILED_TO_REALIZE = "FAILED_TO_REALIZE"
const TransportNodeCollectionState_STATE_IN_PROGRESS = "IN_PROGRESS"
const TransportNodeCollectionState_STATE_PROFILE_MISMATCH = "PROFILE_MISMATCH"
